  (@qs_8, 1, 'Service Quality', 'Service Quality', 0.4000, 'Tidak Bagus', 'Kurang Bagus', 'Bagus', 'Sangat Bagus', 1, 1, 'rating', 'evaluation', 'text', 'Tidak memahami informasi mall dan sering menyebabkan keluhan dari pengunjung atau tenant.', 'Kurang memahami tenant, fasilitas, dan prosedur dasar sehingga sering memberi informasi kurang tepat.', 'Cukup memahami informasi dasar mall, tetapi masih sering perlu mengecek ulang kepada supervisor.', 'Sangat menguasai tenant directory, lokasi fasilitas, event, promo, jam operasional, akses parkir, prosedur lost & found, dan informasi emergency.', 'Ceritakan poin / bukti pendukung alasan pemilihan nilai tersebut', NULL, NULL),
  (@qs_8, 2, 'Responsiveness & SLA', 'Responsiveness & SLA', 0.2000, 'Tidak Bagus', 'Kurang Bagus', 'Bagus', 'Sangat Bagus', 1, 1, 'rating', 'evaluation', 'text', 'Komunikasi buruk, tidak sopan, atau menyebabkan complaint serius dari pengunjung / tenant.', 'Kurang ramah, kurang proaktif, atau beberapa kali menunjukkan sikap tidak profesional.', 'Komunikasi cukup baik, tetapi belum konsisten dalam keramahan, intonasi, atau keaktifan membantu pengunjung.', 'Sangat ramah, sopan, empatik, proaktif menyapa dan membantu pengunjung, serta mampu menjaga emosi saat menghadapi complaint.', 'Ceritakan poin / bukti pendukung alasan pemilihan nilai tersebut', NULL, NULL),
  (@qs_8, 3, 'Manpower', 'Manpower', 0.1500, 'Tidak Bagus', 'Kurang Bagus', 'Bagus', 'Sangat Bagus', 1, 1, 'rating', 'evaluation', 'text', 'Jumlah manpower tidak sesuai kontrak dan sering terjadi pos kosong tanpa pengganti.', 'Sering kekurangan manpower sehingga coverage area, booth informasi, atau pelayanan pengunjung terganggu.', 'Ada beberapa kekurangan manpower, tetapi operasional customer service masih berjalan.', 'Jumlah CS selalu sesuai kebutuhan operasional mall, termasuk weekend, public holiday, event, dan peak hour. Tidak ada kekosongan pos.', 'Ceritakan poin / bukti pendukung alasan pemilihan nilai tersebut', NULL, NULL),
  (@qs_8, 4, 'Grooming & Profesionalisme', 'Grooming & Profesionalisme', 0.2500, 'Tidak Bagus', 'Kurang Bagus', 'Bagus', 'Sangat Bagus', 1, 1, 'rating', 'evaluation', 'text', 'Tidak mengikuti standar grooming dan menunjukkan sikap tidak profesional di area publik mall.', 'Sering tidak sesuai standar grooming, seragam tidak lengkap, atau sikap kerja kurang profesional.', 'Cukup rapi, tetapi belum konsisten mengikuti standar grooming mall.', 'Selalu memakai seragam lengkap, ID card, sepatu sesuai standar, grooming rapi, make up natural / sesuai ketentuan, postur kerja baik, dan bahasa tubuh profesional.', 'Ceritakan poin / bukti pendukung alasan pemilihan nilai tersebut', NULL, NULL),
  (@qs_8, 5, 'Kesimpulan', 'Ceritakan ringkasan kinerja dan isu vendor dalam performance ini', 0.0000, '', '', '', '', 1, 1, 'text', 'evaluation', 'text', NULL, NULL, NULL, NULL, NULL, NULL, NULL)
