-- ====================================================================
-- SECTION B — PO taxonomy seed (311 mapped rows; needs_review excluded)
-- ====================================================================

-- db_backups/vendor_eval_v2_seed_po_taxonomy_20260706.sql
--
-- Vendor Evaluation v2 -- PO-to-taxonomy mapping export.
-- Generated 2026-07-06 from local DB u894129685_workspace (KLG-PROC-I01271,
-- MariaDB 10.4.32), programmatically from live rows. 311 rows, status='mapped'
-- only (excludes 41 'needs_review' rows -- those are unconfirmed and better
-- re-reviewed fresh on the target than carried over as if settled).
--
-- No sensitive contact data (no email/phone/token columns on this table).
-- requestor_names_json contains requestor NAMES only (business context, not
-- contact info).
--
-- >>> IMPORTANT CAVEAT <<<
-- This table is DERIVED data: each row is only meaningful if the target's own
-- `prs` table contains the SAME po_number. There is no FK enforcing this, so
-- importing this file onto a target with a different PO population will create
-- orphaned rows that never match a real PO there.
--
-- FUTURE REFRESH: this population will likely be refreshed later by mapping
-- prs.master_data_id -> master_data on the target (after protected-file-safe
-- reconciliation). Do NOT treat this export as the permanent source of truth.
--
-- RECOMMENDED PATH: on any target with its own live `prs` data (real
-- production), run tools/run_po_taxonomy_mapping.php (dry-run first) directly
-- against that target instead of importing this file -- that regenerates
-- correct, current mappings for whatever POs actually exist there. This export
-- is only a fallback for environments cloning the same PO population (e.g. QA).
--
-- Idempotent: keyed on po_number (UNIQUE). Safe to re-run.
--
-- Apply with (after verifying identity AND confirming PO overlap with target):
--   mysql -h HOST -u USER -p DATABASE < db_backups/vendor_eval_v2_seed_po_taxonomy_20260706.sql

START TRANSACTION;
ON DUPLICATE KEY UPDATE
  vendor_name = VALUES(vendor_name), requestor_names_json = VALUES(requestor_names_json),
  item_descriptions_json = VALUES(item_descriptions_json), line_item_count = VALUES(line_item_count),
  p_group = VALUES(p_group), ticket_type = VALUES(ticket_type),
  taxonomy_level_0 = VALUES(taxonomy_level_0), taxonomy_level_1 = VALUES(taxonomy_level_1),
  sub_category_code = VALUES(sub_category_code), taxonomy_level_2 = VALUES(taxonomy_level_2),
  taxonomy_level_3 = VALUES(taxonomy_level_3), mapping_method = VALUES(mapping_method),
  mapping_confidence = VALUES(mapping_confidence), mapping_reason = VALUES(mapping_reason),
  candidate_taxonomy_json = VALUES(candidate_taxonomy_json), dominant_basis = VALUES(dominant_basis),
  status = VALUES(status), reviewed_by = VALUES(reviewed_by), reviewed_at = VALUES(reviewed_at),
  review_notes = VALUES(review_notes);

-- Verification (expect 311 rows):
SELECT COUNT(*) AS mapped_po_count FROM vendor_eval_po_taxonomy WHERE status = 'mapped';

COMMIT;
